using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEditor;
using UnityEditor.SceneManagement;

namespace C01.Ship.V4.Editor {
    public static class ShipV4Builder {
        public const string Root="Assets/C01ShipV4", ScenePath=Root+"/Scenes/C01_Ship_Multideck.unity", MasterPath=Root+"/Prefabs/C01_SHIP_MULTIDECK_MASTER.prefab", MasterName="C01_SHIP_MULTIDECK_MASTER";
        public static string QA=>Path.GetFullPath(Path.Combine(Application.dataPath,"../C01ShipV4_QA"));
        public static ShipDataV4 Read()=>JsonUtility.FromJson<ShipDataV4>(File.ReadAllText(Root+"/Data/ship_v4.json"));
        public static Vector3 V(float[] a)=>new Vector3(a[0],a[1],a[2]);
        public static Bounds Bounds(PartDataV4 p) {var x=p.outline.Where((v,i)=>i%2==0);var z=p.outline.Where((v,i)=>i%2==1);var b=new Bounds();b.SetMinMax(new Vector3(x.Min(),p.y0,z.Min()),new Vector3(x.Max(),p.y1,z.Max()));return b;}
        public static bool Rectangle(PartDataV4 p) {if(p.outline.Length!=8)return false;var b=Bounds(p);for(int i=0;i<8;i+=2)if(!((Mathf.Abs(p.outline[i]-b.min.x)<.00001f||Mathf.Abs(p.outline[i]-b.max.x)<.00001f)&&(Mathf.Abs(p.outline[i+1]-b.min.z)<.00001f||Mathf.Abs(p.outline[i+1]-b.max.z)<.00001f)))return false;return true;}
        public static Mesh Prism(PartDataV4 p) {
            int n=p.outline.Length/2;var vertices=new List<Vector3>();var triangles=new List<int>();
            var low=Enumerable.Range(0,n).Select(i=>new Vector3(p.outline[2*i],p.y0,p.outline[2*i+1])).ToArray();
            float area=0;for(int i=0;i<n;i++)area+=low[i].x*low[(i+1)%n].z-low[(i+1)%n].x*low[i].z;
            void Tri(Vector3 a,Vector3 b,Vector3 c,Vector3 outward){if(Vector3.Dot(Vector3.Cross(b-a,c-a),outward)<0){var t=b;b=c;c=t;}int j=vertices.Count;vertices.Add(a);vertices.Add(b);vertices.Add(c);triangles.Add(j);triangles.Add(j+1);triangles.Add(j+2);}
            var height=Vector3.up*(p.y1-p.y0);
            for(int i=1;i<n-1;i++){Tri(low[0],low[i],low[i+1],Vector3.down);Tri(low[0]+height,low[i]+height,low[i+1]+height,Vector3.up);}
            for(int i=0;i<n;i++){var a=low[i];var b=low[(i+1)%n];var outward=Vector3.Cross(Vector3.up,b-a)*(area>0?1:-1);Tri(a,b,b+height,outward);Tri(a,b+height,a+height,outward);}
            var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;
        }
        static GameObject Child(string name,Transform parent) {var g=new GameObject(name);g.transform.SetParent(parent,false);return g;}
        static T Asset<T>(string path,T value) where T:UnityEngine.Object {var old=AssetDatabase.LoadAssetAtPath<T>(path);if(old==null){AssetDatabase.CreateAsset(value,path);return value;}EditorUtility.CopySerialized(value,old);UnityEngine.Object.DestroyImmediate(value);EditorUtility.SetDirty(old);return old;}
        static Mesh MeshAsset(string path,Mesh value) {var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null){AssetDatabase.CreateAsset(value,path);return value;}old.Clear();old.SetVertices(value.vertices);old.SetTriangles(value.triangles,0);old.SetNormals(value.normals);old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(value);return old;}
        [MenuItem("Tools/C01 Ship v4/Rebuild")]
        public static void Build() {
            if(EditorApplication.isPlayingOrWillChangePlaymode)throw new InvalidOperationException("Cannot build in PlayMode");
            if(Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Any(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty))throw new InvalidOperationException("Save open scenes before rebuilding v4");
            var data=Read();foreach(string folder in new[]{"Meshes","Materials","Prefabs/Modules","Scenes"})Directory.CreateDirectory(Root+"/"+folder);Directory.CreateDirectory(QA);AssetDatabase.Refresh();
            var materials=new Dictionary<string,Material>();var shader=Shader.Find(GraphicsSettings.defaultRenderPipeline==null&&QualitySettings.renderPipeline==null?"Standard":"Universal Render Pipeline/Lit");if(shader==null)throw new Exception("Host rendering shader unavailable");
            foreach(var m in data.materials){var mat=new Material(shader){name=m.role,enableInstancing=true};var c=m.color;var color=new Color(c[0],c[1],c[2],c.Length>3?c[3]:1);mat.color=color;if(mat.HasProperty("_BaseColor"))mat.SetColor("_BaseColor",color);if(m.role=="SCREEN"||m.role=="THRUST"){mat.EnableKeyword("_EMISSION");mat.SetColor("_EmissionColor",color*1.2f);}if(m.role=="GLASS"&&mat.HasProperty("_Surface")){mat.SetFloat("_Surface",1);mat.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);mat.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);mat.SetFloat("_ZWrite",0);mat.SetFloat("_Cull",0);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.renderQueue=3000;}materials[m.role]=Asset(Root+"/Materials/"+m.role+".mat",mat);}
            var prefabs=new Dictionary<string,GameObject>();
            foreach(var model in data.models){var module=new GameObject(model.id);try{for(int i=0;i<model.parts.Length;i++){var part=model.parts[i];var go=Child(model.id+"__"+i.ToString("D2")+"_"+part.role,module.transform);var marker=go.AddComponent<ShipSolidV4>();marker.modelId=model.id;marker.partIndex=i;marker.role=part.role;var mesh=MeshAsset(Root+"/Meshes/"+model.id+"__"+i.ToString("D2")+".asset",Prism(part));go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=materials[part.role];if(Rectangle(part)){var c=go.AddComponent<BoxCollider>();c.center=mesh.bounds.center;c.size=mesh.bounds.size;}else{var c=go.AddComponent<MeshCollider>();c.sharedMesh=mesh;c.convex=true;}}foreach(var socket in model.sockets??Array.Empty<SocketDataV4>()){var t=Child(socket.name,module.transform).transform;t.localPosition=V(socket.position);t.localRotation=Quaternion.FromToRotation(Vector3.forward,V(socket.normal).normalized);}prefabs[model.id]=PrefabUtility.SaveAsPrefabAsset(module,Root+"/Prefabs/Modules/"+model.id+".prefab");}finally{UnityEngine.Object.DestroyImmediate(module);}}
            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
            RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.32f,.39f,.48f);RenderSettings.fog=false;
            var master=new GameObject(MasterName);var groups=new Dictionary<string,Transform>();var instances=new Dictionary<string,GameObject>();
            foreach(var p in data.placements){string category=p.category??"Other";if(!groups.TryGetValue(category,out var group))groups[category]=group=Child(category,master.transform).transform;var go=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[p.model],group);go.name=p.id;go.transform.SetPositionAndRotation(new Vector3(p.x,p.y,p.z),Quaternion.Euler(0,p.yaw,0));go.transform.localScale=Vector3.one;var m=go.AddComponent<ShipInstanceV4>();m.placementId=p.id;m.modelId=p.model;m.category=p.category;m.zoneId=p.zone;m.deck=p.deck;instances[p.id]=go;}
            var font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");var zones=Child("Zones",master.transform);foreach(var z in data.zones){var go=Child(z.id,zones.transform);go.transform.position=V(z.waypoint);var m=go.AddComponent<ShipZoneV4>();m.zoneId=z.id;m.label=z.label;m.kind=z.kind;m.deck=z.deck;m.floor=z.floor;m.height=z.height;var text=Child("Label",go.transform);text.transform.position=new Vector3((z.bounds[0]+z.bounds[1])*.5f,z.floor+.04f,(z.bounds[2]+z.bounds[3])*.5f);text.transform.rotation=Quaternion.Euler(90,0,0);var tm=text.AddComponent<TextMesh>();tm.font=font;tm.text=z.label;tm.fontSize=40;tm.characterSize=.14f;tm.anchor=TextAnchor.MiddleCenter;tm.color=new Color(.8f,.95f,1);text.GetComponent<MeshRenderer>().sharedMaterial=font.material;text.GetComponent<MeshRenderer>().enabled=false;}
            var gates=new Dictionary<string,ShipGateV4>();var gateRoot=Child("GateControllers",master.transform);
            foreach(var g in data.gates){var go=Child(g.id,gateRoot.transform);go.transform.SetPositionAndRotation(new Vector3(g.x,g.y,g.z),Quaternion.Euler(0,g.yaw,0));var gate=go.AddComponent<ShipGateV4>();gate.id=g.id;gate.leaves=g.leaves.Select(id=>instances[id].transform).ToArray();gate.travel=g.leaves.Select(id=>V(data.placements.Single(p=>p.id==id).travel)).ToArray();foreach(var leaf in gate.leaves){var rb=leaf.gameObject.AddComponent<Rigidbody>();rb.isKinematic=true;rb.useGravity=false;}gates[g.id]=gate;gate.SetImmediate(0);}
            var airlocks=new Dictionary<string,ShipAirlockV4>();foreach(var a in data.airlocks){var air=Child(a.id,gateRoot.transform).AddComponent<ShipAirlockV4>();air.gateA=gates[a.gates[0]];air.gateB=gates[a.gates[1]];air.gateA.interlockAirlock=air;air.gateB.interlockAirlock=air;airlocks[a.id]=air;}
            var lifts=new Dictionary<string,ShipLiftV4>();foreach(var l in data.lifts){var go=Child(l.id,master.transform);var lift=go.AddComponent<ShipLiftV4>();lift.id=l.id;lift.car=Child(l.car,go.transform).transform;lift.car.position=new Vector3(l.x,0,l.z);var rb=lift.car.gameObject.AddComponent<Rigidbody>();rb.isKinematic=true;rb.useGravity=false;foreach(var p in data.placements.Where(p=>p.parent==l.car))instances[p.id].transform.SetParent(lift.car,true);lift.landings=l.landings.Select(id=>gates[id]).ToArray();lift.elevations=l.elevations;lift.footprint=new Vector4(l.bounds[0],l.bounds[1],l.bounds[2],l.bounds[3]);for(int i=0;i<lift.landings.Length;i++){lift.landings[i].interlockLift=lift;lift.landings[i].landingFloor=i;}lift.ResetToFloor(1);lifts[l.id]=lift;}
            var buttons=new List<ShipButtonV4>();foreach(var p in data.placements.Where(p=>!string.IsNullOrEmpty(p.buttonGate)||!string.IsNullOrEmpty(p.buttonLift))){var b=instances[p.id].AddComponent<ShipButtonV4>();b.gateId=p.buttonGate;b.liftId=p.buttonLift;b.floor=p.buttonFloor;if(!string.IsNullOrEmpty(p.buttonGate)){b.gate=gates[p.buttonGate];b.airlock=b.gate.interlockAirlock;}if(!string.IsNullOrEmpty(p.buttonLift))b.lift=lifts[p.buttonLift];var sign=Child("Button_Label",b.transform);sign.transform.localPosition=new Vector3(.11f,.14f,.112f);sign.transform.localRotation=Quaternion.Euler(0,180,0);var text=sign.AddComponent<TextMesh>();text.font=font;text.fontSize=40;text.characterSize=string.IsNullOrEmpty(p.parent)?.02f:.055f;text.anchor=TextAnchor.MiddleCenter;text.text=string.IsNullOrEmpty(p.parent)?b.lift!=null?"WEZWIJ":"BRAMA":p.buttonFloor.ToString();text.color=Color.white;sign.GetComponent<MeshRenderer>().sharedMaterial=font.material;buttons.Add(b);}
            PrefabUtility.SaveAsPrefabAssetAndConnect(master,MasterPath,InteractionMode.AutomatedAction);
            var actor=new GameObject("Ship_Player");actor.transform.SetPositionAndRotation(new Vector3(-1.5f,.02f,22.5f),Quaternion.Euler(0,90,0));var player=actor.AddComponent<CharacterController>();player.height=1.8f;player.radius=.28f;player.center=new Vector3(0,.9f,0);player.stepOffset=.18f;
            var camera=new GameObject("Ship_Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.04f,.06f);camera.nearClipPlane=.05f;camera.farClipPlane=600;camera.orthographic=true;camera.orthographicSize=39;camera.gameObject.AddComponent<AudioListener>();
            var explorer=new GameObject("Ship_Explorer").AddComponent<ShipExplorerV4>();explorer.view=camera;explorer.player=player;explorer.master=master;explorer.gates=gates.Values.ToArray();explorer.lifts=lifts.Values.ToArray();explorer.buttons=buttons.ToArray();foreach(var lift in lifts.Values){lift.player=player;PrefabUtility.RecordPrefabInstancePropertyModifications(lift);}explorer.SetDeck(1);explorer.SetWalking(false);
            var sun=new GameObject("Ship_KeyLight").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.4f;sun.transform.rotation=Quaternion.Euler(48,-35,0);sun.shadows=LightShadows.Soft;
            foreach(var z in data.zones.Where(z=>string.IsNullOrEmpty(z.parent))){var light=new GameObject("Light_"+z.id).AddComponent<Light>();light.type=LightType.Point;light.transform.position=new Vector3((z.bounds[0]+z.bounds[1])*.5f,z.floor+Mathf.Min(z.height-1,4),(z.bounds[2]+z.bounds[3])*.5f);light.range=Mathf.Max(12,z.height*1.6f);light.intensity=3;light.shadows=LightShadows.None;}
            EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),ScenePath);
            EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(ScenePath,true)}.Concat(EditorBuildSettings.scenes.Where(s=>s.path!=ScenePath)).ToArray();AssetDatabase.SaveAssets();
        }
        public static void Export(){Directory.CreateDirectory(QA);AssetDatabase.ExportPackage(Root,Path.Combine(QA,"C01_Ship_Multideck_v4.0.unitypackage"),ExportPackageOptions.Recurse|ExportPackageOptions.IncludeDependencies);}
    }
    public class ShipV4ModelImporter:AssetPostprocessor {void OnPreprocessModel(){if(!assetPath.StartsWith(ShipV4Builder.Root+"/Models/",StringComparison.Ordinal))return;var m=(ModelImporter)assetImporter;m.globalScale=1;m.useFileScale=true;m.isReadable=true;m.importAnimation=false;m.importLights=false;m.importCameras=false;}}
}
